import{_ as n,c as a,b as e,o as t}from"./app-Di-e0zxZ.js";const p={};function o(l,s){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="_14-模块化" tabindex="-1"><a class="header-anchor" href="#_14-模块化"><span>14 模块化</span></a></h1><p>&gt; Last Format Time：8/11/2026 21:45:41</p><p>本笔记由两个 JavaScript 教程目录中的同主题内容合并而成；全部旧知识保留在“旧笔记知识全集（按来源保留）”中，并由导航逐项索引。</p><hr><h2 id="当前前端开发关键要点" tabindex="-1"><a class="header-anchor" href="#当前前端开发关键要点"><span>当前前端开发关键要点</span></a></h2><p>&gt; [!important] 学习优先级：P0 &gt; - 浏览器与现代前端构建默认优先 ESM，理解静态分析、tree shaking 和动态 <code>import()</code>。 &gt; - 明确 ESM 的实时绑定与 CommonJS 导出对象语义，处理好默认导出、具名导出和互操作。 &gt; - 避免隐蔽循环依赖；用清晰分层、依赖方向与按需拆包控制模块边界。</p><hr><h2 id="知识点导航" tabindex="-1"><a class="header-anchor" href="#知识点导航"><span>知识点导航</span></a></h2><h3 id="现代js教程与阮一峰es6-·-7模块-cjs和esm-14-模块化-md" tabindex="-1"><a class="header-anchor" href="#现代js教程与阮一峰es6-·-7模块-cjs和esm-14-模块化-md"><span>[现代JS教程与阮一峰ES6 · 7模块/CJS和ESM](./14 <a href="http://xn--cjrv2hj6u.md" target="_blank" rel="noopener noreferrer">模块化.md</a>)</span></a></h3><ul><li>核心区别对比表</li><li>详细解释</li><li>来源与历史</li><li>语法</li><li>加载方式：静态 vs. 动态</li><li>加载时机：同步 vs. 异步</li><li>值引用 vs. 值拷贝</li><li>运行环境</li><li>总结与如何选择</li></ul><h3 id="现代js教程与阮一峰es6-·-7模块-module-模块-语法-14-模块化-md" tabindex="-1"><a class="header-anchor" href="#现代js教程与阮一峰es6-·-7模块-module-模块-语法-14-模块化-md"><span>[现代JS教程与阮一峰ES6 · 7模块/Module（模块）语法](./14 <a href="http://xn--cjrv2hj6u.md" target="_blank" rel="noopener noreferrer">模块化.md</a>)</span></a></h3><ul><li>导入导出类型不匹配错误</li><li>路径错误</li><li>重复导入</li><li>导出变量未定义</li><li>循环依赖</li><li>导入导出的语法错误</li></ul><hr><h2 id="现代前端补充与纠错" tabindex="-1"><a class="header-anchor" href="#现代前端补充与纠错"><span>现代前端补充与纠错</span></a></h2><p>&gt; [!info] 修改标记 &gt; - <em>【修正】</em>：旧教程中错误、过时或容易误导的内容。 &gt; - <em>【补充】</em>：旧教程未覆盖、但当前前端开发需要掌握的内容。 &gt; - <em>【修正代码】</em>：替换或校正了旧代码示例。</p><p>&gt; [!warning] 下方 CommonJS/ESM 对比含历史化简。现代 Node.js 已能在满足条件时由 <code>require()</code> 加载同步 ESM，不能再笼统写成“完全不能加载”。</p><h3 id="esm-核心语义" tabindex="-1"><a class="header-anchor" href="#esm-核心语义"><span>ESM 核心语义</span></a></h3><ul><li><em>【补充】</em> ESM 的导入是只读实时绑定，静态结构支持依赖分析、Tree Shaking 和循环依赖检查；模块只求值一次。</li><li><em>【补充】</em> <code>import()</code> 返回 Promise，适合按路由/功能拆包；<code>import.meta</code> 提供模块环境信息。</li><li><em>【补充】</em> 浏览器相对导入通常需要完整路径；Node/打包器解析还受 <code>package.json</code> 的 <code>type</code>、<code>exports</code>、<code>imports</code> 和条件导出影响。</li><li><em>【补充】</em> Tree Shaking 依赖静态 ESM 与副作用分析；<code>sideEffects</code> 配置错误可能删掉必要代码或保留无用代码。</li></ul><h3 id="commonjs-边界" tabindex="-1"><a class="header-anchor" href="#commonjs-边界"><span>CommonJS 边界</span></a></h3><ul><li><em>【修正】</em> <code>require()</code> 返回缓存的 <code>module.exports</code> 值；若它是对象，消费者拿到的是该对象引用，不能概括为“值拷贝”。解构赋值才会把当时属性值取到局部绑定。</li><li><em>【修正】</em> 当前 Node.js 可用 <code>require()</code> 加载满足同步条件、且不含顶层 <code>await</code> 的 ESM；具体限制随 Node 版本变化，工程文档应标明运行时版本。</li><li><em>【补充】</em> CJS 与 ESM 互操作的默认导入、命名导入和循环依赖容易产生差异，库发布应通过真实 Node/打包器矩阵验证。</li></ul><hr><h2 id="旧笔记知识全集-按来源保留" tabindex="-1"><a class="header-anchor" href="#旧笔记知识全集-按来源保留"><span>旧笔记知识全集（按来源保留）</span></a></h2><h3 id="现代js教程与阮一峰es6-·-7模块-cjs和esm" tabindex="-1"><a class="header-anchor" href="#现代js教程与阮一峰es6-·-7模块-cjs和esm"><span>现代JS教程与阮一峰ES6 · 7模块/CJS和ESM</span></a></h3><p>好的，ESM（ECMAScript Modules）和 CJS（CommonJS）是 JavaScript 中两种最主要的模块系统。它们在设计哲学、语法和运行方式上有根本性的区别。</p><p>以下是它们之间的核心区别，我用一个对比表格来清晰展示，然后进行详细解释。</p><h5 id="核心区别对比表" tabindex="-1"><a class="header-anchor" href="#核心区别对比表"><span>核心区别对比表</span></a></h5><table><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">ESM (ECMAScript Modules)</th><th style="text-align:left;">CJS (CommonJS)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>来源与标准</strong></td><td style="text-align:left;"><strong>语言标准</strong> (ES6 / ES2015)</td><td style="text-align:left;"><strong>社区规范</strong> (主要用于 Node.js 环境)</td></tr><tr><td style="text-align:left;"><strong>语法 - 导出</strong></td><td style="text-align:left;"><code>export default myComponent;</code> &lt;br&gt; <code>export const foo = &#39;bar&#39;;</code></td><td style="text-align:left;"><code>module.exports = myComponent;</code> &lt;br&gt; <code>exports.foo = &#39;bar&#39;;</code></td></tr><tr><td style="text-align:left;"><strong>语法 - 导入</strong></td><td style="text-align:left;"><code>import myComponent from &#39;./module.js&#39;;</code> &lt;br&gt; <code>import { foo } from &#39;./module.js&#39;;</code></td><td style="text-align:left;"><code>const myComponent = require(&#39;./module&#39;);</code></td></tr><tr><td style="text-align:left;"><strong>加载方式</strong></td><td style="text-align:left;"><strong>静态</strong> (编译时)</td><td style="text-align:left;"><strong>动态</strong> (运行时)</td></tr><tr><td style="text-align:left;"><strong>加载时机</strong></td><td style="text-align:left;">静态链接；浏览器可异步获取，<code>top-level await</code> 会使求值异步</td><td style="text-align:left;"><code>require()</code> 通常同步加载与求值</td></tr><tr><td style="text-align:left;"><strong>运行环境</strong></td><td style="text-align:left;"><strong>现代浏览器</strong>、<strong>现代 Node.js</strong></td><td style="text-align:left;"><strong>Node.js</strong> (传统)、<strong>打包工具</strong> (如 Webpack)</td></tr><tr><td style="text-align:left;"><strong>Tree Shaking</strong></td><td style="text-align:left;">静态结构便于打包器分析</td><td style="text-align:left;">动态 <code>require()</code> 较难静态分析</td></tr><tr><td style="text-align:left;"><strong>导入语义</strong></td><td style="text-align:left;">导入的是只读实时绑定</td><td style="text-align:left;">返回缓存的 <code>module.exports</code> 值；对象通常共享引用</td></tr><tr><td style="text-align:left;"><strong>文件后缀</strong></td><td style="text-align:left;">通常为 <code>.js</code>, <code>.mjs</code></td><td style="text-align:left;">通常为 <code>.js</code>, <code>.cjs</code></td></tr><tr><td style="text-align:left;"><strong>顶层的 <code>this</code></strong></td><td style="text-align:left;"><code>undefined</code></td><td style="text-align:left;">指向 <code>module.exports</code></td></tr></tbody></table><h5 id="详细解释" tabindex="-1"><a class="header-anchor" href="#详细解释"><span>详细解释</span></a></h5><h5 id="来源与历史" tabindex="-1"><a class="header-anchor" href="#来源与历史"><span>来源与历史</span></a></h5><ul><li><strong>CJS (CommonJS)</strong>：诞生于2009年，旨在为浏览器之外的 JavaScript（主要是 Node.js）提供模块系统。它不是一个语言标准，而是一个社区规范。Node.js 的早期版本完全基于 CJS。</li><li><strong>ESM (ECMAScript Modules)</strong>：是 JavaScript 语言在 <strong>ES2015 (ES6)</strong> 标准中正式引入的模块系统。它的目标是为 JavaScript 提供一个统一的、官方的模块方案，无论是在浏览器还是其他环境中。</li></ul><h5 id="语法" tabindex="-1"><a class="header-anchor" href="#语法"><span>语法</span></a></h5><p>这是最直观的区别。</p><ul><li><strong>CJS 使用 <code>require()</code> 和 <code>module.exports</code>/<code>exports</code></strong>:</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">    <span class="token comment">// 导出</span></span>
<span class="line">    module<span class="token punctuation">.</span>exports <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">      functionA<span class="token punctuation">,</span></span>
<span class="line">      variableB</span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">// 或者</span></span>
<span class="line">    exports<span class="token punctuation">.</span>functionA <span class="token operator">=</span> functionA<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 导入</span></span>
<span class="line">    <span class="token keyword">const</span> myModule <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&#39;./my-module&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">const</span> <span class="token punctuation">{</span> functionA <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&#39;./my-module&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>ESM 使用 <code>import</code> 和 <code>export</code></strong>:</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">    <span class="token comment">// 导出</span></span>
<span class="line">    <span class="token keyword">export</span> <span class="token keyword">default</span> functionA<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">export</span> <span class="token keyword">const</span> variableB <span class="token operator">=</span> <span class="token string">&#39;Hello&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 导入</span></span>
<span class="line">    <span class="token keyword">import</span> myModule <span class="token keyword">from</span> <span class="token string">&#39;./my-module.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">import</span> <span class="token punctuation">{</span> variableB <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./my-module.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token comment">// 或者混合导入</span></span>
<span class="line">    <span class="token keyword">import</span> myDefault<span class="token punctuation">,</span> <span class="token punctuation">{</span> namedExport <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./my-module.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="加载方式-静态-vs-动态" tabindex="-1"><a class="header-anchor" href="#加载方式-静态-vs-动态"><span>加载方式：静态 vs. 动态</span></a></h5><p>这是最关键的区别，它导致了其他所有差异。</p><ul><li><p><strong>ESM 是静态的</strong>：</p><ul><li><code>import</code> 命令必须在模块的顶层作用域使用，不能写在条件判断或函数内。</li><li>这意味着模块的依赖关系在<strong>代码编译阶段（编译时）</strong> 就已经确定下来了。</li><li><strong>优势</strong>：这使得打包工具（如 Webpack、Rollup）可以轻松地进行<strong>静态分析</strong>，从而实现 <code>Tree Shaking</code>（摇树优化），剔除那些从未被导出和导入的代码，极大减小最终打包体积。</li></ul></li><li><p><strong>CJS 是动态的</strong>：</p><ul><li><code>require()</code> 是一个函数，可以在代码的<strong>任何地方</strong>被调用，包括条件语句和函数内部。</li><li>这意味着模块的依赖关系要到<strong>代码执行阶段（运行时）</strong> 才能确定。</li><li><strong>劣势</strong>：无法在打包前静态分析出所有依赖，因此难以实现完美的 Tree Shaking。</li></ul></li></ul><h5 id="加载时机-同步-vs-异步" tabindex="-1"><a class="header-anchor" href="#加载时机-同步-vs-异步"><span>加载时机：同步 vs. 异步</span></a></h5><ul><li><strong>CJS 是同步加载的</strong>：<code>require()</code> 语句会同步地阻塞代码执行，直到模块被加载并执行完毕，才会继续执行后面的代码。这在服务器端（Node.js）读写本地文件是可行的。 <em>8/11/26 【修正】原内容：ESM 一概属于异步加载；修改点：静态链接、宿主获取和模块求值是不同阶段，浏览器获取模块通常异步，<code>top-level await</code> 会让依赖图求值异步。</em></li><li><strong>ESM 先静态链接，再由宿主加载和求值</strong>：浏览器会获取模块依赖图且不按经典脚本方式阻塞 HTML 解析；是否发生异步求值还取决于 <code>top-level await</code>。</li></ul><h5 id="值引用-vs-值拷贝" tabindex="-1"><a class="header-anchor" href="#值引用-vs-值拷贝"><span>值引用 vs. 值拷贝</span></a></h5><p>这个区别在处理循环依赖时尤为明显。</p><ul><li><strong>ESM 是值的动态只读引用</strong>： <ul><li>导入绑定会实时读取导出模块中的绑定，不应解释成两个模块指向同一个内存地址。</li><li>当导出的模块修改了一个值，导入模块中看到的值也会随之改变。</li><li>导入的值是<strong>只读</strong>的，你不能直接修改它（除非导出的是一个对象，你可以修改其属性）。</li></ul></li></ul><p><em>8/11/26 【修正】原内容：CJS 导入统一属于值拷贝；修改点：<code>require()</code> 返回缓存的 <code>module.exports</code> 值，对象导出通常是共享引用，解构才取得当时的属性值。</em></p><ul><li><strong>CJS 的导入语义取决于导出值和消费方式</strong>： <ul><li><code>require()</code> 返回缓存的 <code>module.exports</code> 值；若导出对象，消费者通常共享同一个对象引用。</li><li><code>const { value } = require(...)</code> 会在解构时取得属性值；后续重新赋值导出属性不会自动更新这个局部变量。</li></ul></li></ul><h3 id="示例" tabindex="-1"><a class="header-anchor" href="#示例"><span>示例</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// counter.js (ESM)</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">let</span> count <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token function-variable function">increment</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> count<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// main.js (ESM)</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> count<span class="token punctuation">,</span> increment <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./counter.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>count<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 0</span></span>
<span class="line"><span class="token function">increment</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>count<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 1 (值被改变了，因为是对同一内存地址的引用)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// counter.js (CJS)</span></span>
<span class="line"><span class="token keyword">let</span> count <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">exports<span class="token punctuation">.</span><span class="token function-variable function">increment</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> count<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">exports<span class="token punctuation">.</span><span class="token function-variable function">getCount</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> count<span class="token punctuation">;</span> <span class="token comment">// 需要一个getter来获取最新值</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// main.js (CJS)</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token punctuation">{</span> increment<span class="token punctuation">,</span> getCount <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&#39;./counter&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> count <span class="token operator">=</span> <span class="token function">getCount</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>count<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 0</span></span>
<span class="line"><span class="token function">increment</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token function">getCount</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 1</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>count<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 0 (原始的count变量仍是拷贝时的值，未变)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="运行环境" tabindex="-1"><a class="header-anchor" href="#运行环境"><span>运行环境</span></a></h5><ul><li><strong>CJS</strong>：<strong>原生支持于 Node.js</strong>。在浏览器中直接使用需要打包工具处理。</li><li><strong>ESM</strong>： <ul><li><strong>现代浏览器</strong> 已原生支持 (<code>&amp;lt;script type=&quot;module&quot;&amp;gt;</code>)。</li><li><strong>现代 Node.js</strong> (v12+) 也已原生支持，通常通过 <code>.mjs</code> 文件扩展名或 <code>package.json</code> 中设置 <code>&quot;type&quot;: &quot;module&quot;</code> 来启用。</li></ul></li></ul><h5 id="总结与如何选择" tabindex="-1"><a class="header-anchor" href="#总结与如何选择"><span>总结与如何选择</span></a></h5><ul><li><strong>新项目</strong>：<strong>毫无疑问应该使用 ESM</strong>。它是语言标准，支持 Tree Shaking，并且是未来的方向。</li><li><strong>Node.js 开发</strong>： <ul><li>新项目建议在 <code>package.json</code> 中设置 <code>&quot;type&quot;: &quot;module&quot;</code> 来使用 ESM。</li><li>旧的库和项目可能仍然使用 CJS。</li></ul></li><li><strong>旧项目/库</strong>：如果是一个旧的 CJS 项目，除非有充分理由，否则迁移到 ESM 的成本可能较高。但如果要发布新的库，最好提供 ESM 格式的版本，以便用户能进行 Tree Shaking。</li><li><strong>在 Node.js 中互操作</strong>： <ul><li>在 ESM 模块中可以使用 <code>import()</code> 动态导入 CJS 模块。 <em>8/11/26 【修正】原内容：CJS 无法用 <code>require()</code> 加载 ESM；修改点：当前 Node.js 可加载满足同步条件且不含顶层 <code>await</code> 的 ESM，限制应按运行时版本确认。</em></li></ul></li><li>CJS/ESM 互操作应按 Node.js 目标版本、模块同步性和包导出配置验证。</li></ul><p>简单来说，<strong>ESM 是现代化开发的标配，而 CJS 是历史遗留和特定环境（如传统 Node.js）下的产物</strong>。</p><h3 id="现代js教程与阮一峰es6-·-7模块-module-模块-语法" tabindex="-1"><a class="header-anchor" href="#现代js教程与阮一峰es6-·-7模块-module-模块-语法"><span>现代JS教程与阮一峰ES6 · 7模块/Module（模块）语法</span></a></h3><p>在ES6模块中，导入和导出的使用如果不规范，很容易产生错误。以下是一些常见错误及其解决方法：</p><h5 id="导入导出类型不匹配错误" tabindex="-1"><a class="header-anchor" href="#导入导出类型不匹配错误"><span>导入导出类型不匹配错误</span></a></h5><p><strong>错误表现</strong>：如前面提到的，使用默认导出的模块却用具名导入方式，或者使用具名导出的模块却用默认导入方式，导致找不到对应导出项，报错 <code>No matching export in &quot;xxx&quot; for import &quot;xxx&quot;</code> 。 <strong>错误示例</strong>：</p><ul><li><strong>导出文件（<code>module.js</code>）</strong>：</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> data <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">message</span><span class="token operator">:</span> <span class="token string">&#39;Hello&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">default</span> data<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>导入文件（<code>main.js</code>）</strong>：</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> data <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./module.js&#39;</span><span class="token punctuation">;</span> <span class="token comment">// 错误，这里使用了具名导入，但module.js是默认导出</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>解决方法</strong>：</p><ul><li>如果是默认导出，导入时直接使用默认导入形式：</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> data <span class="token keyword">from</span> <span class="token string">&#39;./module.js&#39;</span><span class="token punctuation">;</span> <span class="token comment">// 正确，使用默认导入</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>如果想使用具名导入，将导出文件修改为具名导出：</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> data <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">message</span><span class="token operator">:</span> <span class="token string">&#39;Hello&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>然后在导入文件中使用具名导入：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> data <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./module.js&#39;</span><span class="token punctuation">;</span> <span class="token comment">// 正确，使用具名导入</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h5 id="路径错误" tabindex="-1"><a class="header-anchor" href="#路径错误"><span>路径错误</span></a></h5><p><strong>错误表现</strong>：导入模块时指定了错误的文件路径，导致无法找到模块，报错类似于 <code>Cannot find module &#39;xxx&#39;</code> 。 <strong>错误示例</strong>：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> someFunction <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;../wrongPath/module.js&#39;</span><span class="token punctuation">;</span> <span class="token comment">// 假设模块实际在../correctPath/module.js</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>解决方法</strong>：仔细检查并确保导入路径与模块实际存放路径一致，修改为正确路径：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> someFunction <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;../correctPath/module.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h5 id="重复导入" tabindex="-1"><a class="header-anchor" href="#重复导入"><span>重复导入</span></a></h5><p><strong>错误表现</strong>：多次导入同一个模块，虽然在ES6中重复导入不会报错，但可能会导致代码可读性变差，且存在不必要的资源消耗。 <strong>错误示例</strong>：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> someFunction <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./module.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> anotherFunction <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./module.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 又一次导入整个模块</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token operator">*</span> <span class="token keyword">as</span> module <span class="token keyword">from</span> <span class="token string">&#39;./module.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>解决方法</strong>：尽量将多次导入合并为一次导入，按需获取需要的导出项：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> someFunction<span class="token punctuation">,</span> anotherFunction <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./module.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>或者使用通配符导入后按需访问：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token operator">*</span> <span class="token keyword">as</span> module <span class="token keyword">from</span> <span class="token string">&#39;./module.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> result1 <span class="token operator">=</span> module<span class="token punctuation">.</span><span class="token function">someFunction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> result2 <span class="token operator">=</span> module<span class="token punctuation">.</span><span class="token function">anotherFunction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="导出变量未定义" tabindex="-1"><a class="header-anchor" href="#导出变量未定义"><span>导出变量未定义</span></a></h5><p><strong>错误表现</strong>：在导出时，导出了一个未定义的变量，导致运行时报错。 <strong>错误示例</strong>：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">export</span> <span class="token punctuation">{</span> nonExistentVariable <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token comment">// nonExistentVariable未定义</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>解决方法</strong>：确保导出的变量已经被正确声明和赋值：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> definedVariable <span class="token operator">=</span> <span class="token string">&#39;This is defined&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token punctuation">{</span> definedVariable <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h5 id="循环依赖" tabindex="-1"><a class="header-anchor" href="#循环依赖"><span>循环依赖</span></a></h5><p><strong>错误表现</strong>：模块A导入模块B，而模块B又导入模块A，形成循环引用，可能导致某些变量未初始化就被使用，从而报错。 <strong>错误示例</strong>：</p><ul><li><strong><code>moduleA.js</code></strong>：</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> bFunction <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./moduleB.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token function-variable function">aFunction</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;Inside aFunction&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">bFunction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong><code>moduleB.js</code></strong>：</li></ul><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> aFunction <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./moduleA.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token function-variable function">bFunction</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;Inside bFunction&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">aFunction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>解决方法</strong>：</p><ul><li>重构代码，避免循环依赖，比如将两个模块中互相依赖的部分提取到一个独立的新模块中。</li><li>如果无法避免循环依赖，可以尽量确保在循环引用中，被使用的变量在引用前已经被正确初始化。例如，在Node.js环境中，ES6模块的加载机制会先扫描所有导入导出语句，然后按照一定顺序执行模块代码，合理安排代码执行顺序有时能避免问题。</li></ul><h5 id="导入导出的语法错误" tabindex="-1"><a class="header-anchor" href="#导入导出的语法错误"><span>导入导出的语法错误</span></a></h5><p><strong>错误表现</strong>：在使用导入导出语法时，写错关键字或者语法格式，比如忘记写 <code>export</code> 或者 <code>import</code> 等，导致语法错误。 <strong>错误示例</strong>：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> <span class="token function-variable function">myFunction</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;Function&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token punctuation">{</span> <span class="token comment">// 这里少了export关键字，不是一个正确的导出语句</span></span>
<span class="line">    <span class="token function">myFunction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>解决方法</strong>：仔细检查导入导出的语法，确保关键字拼写正确，语句格式符合ES6规范。比如上面的代码修改为：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> <span class="token function-variable function">myFunction</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;Function&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">myExportedFunction</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">myFunction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>通过<code>export</code>命令显式指定输出的代码，再通过<code>import</code>命令输入。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// ES6模块</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> stat<span class="token punctuation">,</span> exists<span class="token punctuation">,</span> readFile <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;fs&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>ES6 的模块自动采用严格模式，不管你有没有在模块头部加上<code>&quot;use strict&quot;;</code>。 一个模块就是一个独立的文件。该文件内部的所有变量，外部无法获取。如果你希望外部能够读取模块内部的某个变量，就必须使用<code>export</code>关键字输出该变量。下面是一个 JS 文件，里面使用<code>export</code>命令输出变量。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// profile.js</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">var</span> firstName <span class="token operator">=</span> <span class="token string">&#39;Michael&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">var</span> lastName <span class="token operator">=</span> <span class="token string">&#39;Jackson&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">var</span> year <span class="token operator">=</span> <span class="token number">1958</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">或者<span class="token keyword">export</span> <span class="token punctuation">{</span>firstName<span class="token punctuation">,</span>lastName<span class="token punctuation">,</span>year<span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>通常情况下，<code>export</code>输出的变量就是本来的名字，但是可以使用<code>as</code>关键字重命名。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">v1</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">v2</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">export</span> <span class="token punctuation">{</span></span>
<span class="line">  v1 <span class="token keyword">as</span> streamV1<span class="token punctuation">,</span></span>
<span class="line">  v2 <span class="token keyword">as</span> streamV2<span class="token punctuation">,</span></span>
<span class="line">  v2 <span class="token keyword">as</span> streamLatestVersion</span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>上面代码使用<code>as</code>关键字，重命名了函数<code>v1</code>和<code>v2</code>的对外接口。重命名后，<code>v2</code>可以用不同的名字输出两次。</p><p>需要特别注意的是，<code>export</code>命令规定的是对外的接口，必须与模块内部的变量建立一一对应关系。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 报错</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 报错</span></span>
<span class="line"><span class="token keyword">var</span> m <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> m<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>上面两种写法都会报错，因为没有提供对外的接口。第一种写法直接输出 1，第二种写法通过变量<code>m</code>，还是直接输出 1。<code>1</code>只是一个值，不是接口。正确的写法是下面这样。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 写法一</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">var</span> m <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 写法二</span></span>
<span class="line"><span class="token keyword">var</span> m <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token punctuation">{</span>m<span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 写法三</span></span>
<span class="line"><span class="token keyword">var</span> n <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token punctuation">{</span>n <span class="token keyword">as</span> m<span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>上面三种写法都是正确的，规定了对外的接口<code>m</code>。其他脚本可以通过这个接口，取到值<code>1</code>。它们的实质是，在接口名与模块内部变量之间，建立了一一对应的关系。</p><p>同样的，<code>function</code>和<code>class</code>的输出，也必须遵守这样的写法。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 报错</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">f</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">export</span> f<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 正确</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">f</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 正确</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">f</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token punctuation">{</span>f<span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>目前，export 命令能够对外输出的就是三种接口：函数（Functions），类（Classes），var、let、const 声明的变量（Variables）。</p><p>另外，<code>export</code>语句输出的接口，与其对应的值是动态绑定关系，即通过该接口，可以取到模块内部实时的值。 <code>export</code>命令可以出现在模块的任何位置，只要处于模块顶层就可以。如果处于块级作用域内，就会报错，下一节的<code>import</code>命令也是如此。这是因为处于条件代码块之中，就没法做静态优化了，违背了 ES6 模块的设计初衷。</p><p>如果想为输入的变量重新取一个名字，<code>import</code>命令要使用<code>as</code>关键字，将输入的变量重命名。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> lastName <span class="token keyword">as</span> surname <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./profile.js&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>import</code>命令输入的变量都是只读的，因为它的本质是输入接口。也就是说，不允许在加载模块的脚本里面，改写接口。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span>a<span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./xxx.js&#39;</span></span>
<span class="line"></span>
<span class="line">a <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token comment">// Syntax Error : &#39;a&#39; is read-only;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>import</code>后面的<code>from</code>指定模块文件的位置，可以是相对路径，也可以是绝对路径。如果不带有路径，只是一个模块名，那么必须有配置文件，告诉 JavaScript 引擎该模块的位置。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> myMethod <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;util&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>上面代码中，<code>util</code>是模块文件名，由于不带有路径，必须通过配置，告诉引擎怎么取到这个模块。</p><p>注意，<code>import</code>命令具有提升效果，会提升到整个模块的头部，首先执行。</p><p>为了给用户提供方便，让他们不用阅读文档就能加载模块，就要用到<code>export default</code>命令，为模块指定默认输出。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// export-default.js</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">default</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>上面代码是一个模块文件<code>export-default.js</code>，它的默认输出是一个函数。</p><p>其他模块加载该模块时，<code>import</code>命令可以为该匿名函数指定任意名字。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// import-default.js</span></span>
<span class="line"><span class="token keyword">import</span> customName <span class="token keyword">from</span> <span class="token string">&#39;./export-default&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token function">customName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;foo&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>上面代码的<code>import</code>命令，可以用任意名称指向<code>export-default.js</code>输出的方法，这时就不需要知道原模块输出的函数名。需要注意的是，这时<code>import</code>命令后面，不使用大括号。</p><p>如果在一个模块之中，先输入后输出同一个模块，<code>import</code>语句可以与<code>export</code>语句写在一起。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">export</span> <span class="token punctuation">{</span> foo<span class="token punctuation">,</span> bar <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;my_module&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 可以简单理解为</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> foo<span class="token punctuation">,</span> bar <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;my_module&#39;</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token punctuation">{</span> foo<span class="token punctuation">,</span> bar <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,130)])])}const i=n(p,[["render",o]]),r=JSON.parse('{"path":"/notes/obsidian/%E5%89%8D%E7%AB%AF/%E4%B8%89%E4%BB%B6%E5%A5%97/JS/JavaScript/14%20%E6%A8%A1%E5%9D%97%E5%8C%96.html","title":"14 模块化","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/前端/三件套/JS/JavaScript/14 模块化.md"}');export{i as comp,r as data};
